import { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } from 'three';
import { MeshStandardNodeMaterial, color, texture } from 'three/webgpu';
import { uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // Create local lighting to avoid dead lighting
  const localAmbient = new AmbientLight(0xffffff, 0.2);
  group.add(localAmbient);

  const localLight = new DirectionalLight(0xff2a38, 1.2); // Accent tint
  localLight.position.set(2, 3, 4);
  group.add(localLight);

  // Background Backdrop (Stage Integration to prevent FLAT_VOID defect)
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.8,
    metalness: 0.1,
  });

  // Custom TSL gradient for backdrop
  const gradUv = uv();
  const cInk = color('#16161d');
  const cSurface = color('#0b0b10');
  backdropMat.colorNode = gradUv.y.mix(cInk, cSurface);

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Main Card Container (Interactive)
  const cardGroup = new Group();
  group.add(cardGroup);

  // Card Geometry & Material
  const cardGeom = new PlaneGeometry(3.2, 2.0);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.55,
    transparent: true,
  });

  const cardMesh = new Mesh(cardGeom, cardMat);
  cardGroup.add(cardMesh);

  // Load Image Texture if available
  const imgUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  }).catch(() => {
    // Fallback if texture fails: clean surface color
    cardMat.colorNode = color('#e8ecf2').mix(color('#0b0b10'), 0.8);
    cardMat.needsUpdate = true;
  });

  // Text Rendering (using ctx.fontAtlas)
  // Retrieve display text from configuration, defaulting to spec values
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryText = textItems[0]?.text ?? "Journal 2";

  const textLabel = ctx.fontAtlas.createText(primaryText, {
    fontSize: 32, // Display size, corresponding to spec 39px 400
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.5
  });
  // Center label over card
  textLabel.position.set(0, -0.6, 0.05);
  cardGroup.add(textLabel);

  // Interactive Bounds for Raycasting hover/clicks
  const hitGeom = new PlaneGeometry(3.2, 2.0);
  const hitMat = new MeshStandardNodeMaterial({ visible: false });
  const hitMesh = new Mesh(hitGeom, hitMat);
  hitMesh.position.set(0, 0, 0.1);
  cardGroup.add(hitMesh);

  // GSAP Animations & Interactive States
  const state = { hovered: false };
  let hoverTimeline = null;

  const onOver = () => {
    if (state.hovered) return;
    state.hovered = true;

    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    // Hover lift: rise-in subtle translation (0.15 scene units)
    hoverTimeline.to(cardGroup.position, {
      z: 0.15,
      y: 0.05,
      duration: 0.3,
      ease: 'power2.out'
    });
    // Add subtle accent tint to backdrop/lighting
    hoverTimeline.to(localLight, {
      intensity: 1.5,
      duration: 0.3
    }, 0);
  };

  const onOut = () => {
    state.hovered = false;
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(cardGroup.position, {
      z: 0.0,
      y: 0.0,
      duration: 0.4,
      ease: 'power3.out'
    });
    hoverTimeline.to(localLight, {
      intensity: 1.2,
      duration: 0.4
    }, 0);
  };

  const onClick = () => {
    // Native press-down animation
    const clickTimeline = gsap.timeline();
    clickTimeline.to(cardGroup.scale, {
      x: 0.95,
      y: 0.95,
      duration: 0.12,
      ease: 'back.out(2)'
    }).to(cardGroup.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.3,
      ease: 'power4.out'
    });

    // Emit event as configured
    ctx.emit('hub-journal.select', { id: 'journal-2', source: 'card-label' });
  };

  // Wire Interaction Listeners via userData.handlers
  hitMesh.userData.handlers = {
    pointerover: onOver,
    pointerout: onOut,
    click: onClick
  };

  // Apply Cinematic Primitives (e.g., parallax-scroll)
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [{ name: 'parallax-scroll', params: { intensity: 0.25 } }];

  for (const prim of primitives) {
    if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
      const pInstance = ctx.primitives[prim.name](cardGroup, prim.params);
      if (pInstance) {
        primitiveInstances.push(pInstance);
      }
    }
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    primitiveInstances.forEach(inst => {
      if (typeof inst.cleanup === 'function') inst.cleanup();
    });
    cardGeom.dispose();
    cardMat.dispose();
    hitGeom.dispose();
    hitMat.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();
  };

  return group;
}
